/** Same growth/credit producer for every owner. Caller supplies canonical film-ID order. */
export function applyReleaseCareers(seed:string, source:Talent[], records:readonly ReleaseGrowthRecord[]):
  {talent:Talent[];careerEvents:TalentCareerEvent[]} {
  let talent=source
  const newCareerEvents:TalentCareerEvent[]=[]
    // Index into the current talent list for O(1) resolution as it evolves.
    const byId = new Map<string, Talent>()
    for (const t of talent) byId.set(t.id, t)

    for (const rec of records) {
      // D-14: snapshot each participant's PRE-development state for the frozen career
      // event's before→after (engaged films only; participants captured at greenlight).
      const parts = rec.filmResult.participants
      const beforeById = new Map<string, Talent>()
      if (parts !== undefined) {
        for (const p of flattenParticipants(parts)) {
          const cur = byId.get(p.talentId)
          if (cur !== undefined) beforeById.set(p.talentId, cur)
        }
      }

      // 1. DEVELOPMENT (D-9.8) — UNCHANGED. Craft grows in the performed discipline.
      for (const performer of rec.develop.performers) {
        const current = byId.get(performer.talentId)
        if (current === undefined) continue // craft with no hire etc. — nothing to develop
        const devStream = stream(seed, 'develop', `${rec.develop.productionId}:${performer.talentId}`)
        const developed = developTalent(current, performer.discipline, rec.develop.ctx, devStream)
        byId.set(performer.talentId, developed)
      }

      // 2. D-14 STAR POWER (fame) — engaged-only (requires frozen participants), so M0A
      //    is untouched. DETERMINISTIC (no RNG): the delta comes only from realized reach,
      //    role, audience response, forecast comparison, and current fame. Applied to the
      //    POST-development talent → affects FUTURE films only; the just-resolved film's
      //    economics (opening/legs/total, computed in step 3 from pre-tick fame) are
      //    untouched. One frozen TalentCareerEvent per participant.
      if (parts !== undefined) {
        const concept = rec.develop.ctx.concept
        for (const p of flattenParticipants(parts)) {
          const before = beforeById.get(p.talentId)
          const developed = byId.get(p.talentId)
          if (before === undefined || developed === undefined) continue
          const sp = computeStarPowerDelta({
            fameBefore: developed.fame,
            role: p.role,
            realizedTotal: rec.filmResult.boxOffice.total,
            audienceScore: rec.broadcast.weightedAudienceScore,
            expectedTotal: rec.filmResult.forecast ? rec.filmResult.forecast.expectedTotal : null,
          })
          const withFame: Talent = { ...developed, fame: clamp(developed.fame + sp.delta, 0, 100) }
          byId.set(p.talentId, withFame)
          newCareerEvents.push(
            buildTalentCareerEvent({
              talentBefore: before,
              talentAfter: withFame,
              role: p.role,
              discipline: roleDiscipline(p.role),
              filmId: rec.develop.productionId,
              filmTitle: concept.title,
              releaseWeek: rec.filmResult.releaseTick,
              genre: concept.genre,
              realizedOpening: rec.filmResult.boxOffice.opening,
              realizedTotal: rec.filmResult.boxOffice.total,
              audienceScore: rec.broadcast.weightedAudienceScore,
              criticScore: rec.filmResult.criticScore,
              sp,
            }),
          )
        }
      }
    }

    // Rebuild the array in the ORIGINAL talent order (stable serialization),
    // substituting developed objects; untouched talent shared by reference.
    talent = talent.map((t) => byId.get(t.id) ?? t)
  return {talent,careerEvents:newCareerEvents}
}

function staff(state:GameState,h:HollywoodState,b:RivalBusiness,talent:Talent[],week:number,extraRoles:readonly Talent['role'][]=[]):Talent[] {
  const reserveAfterOffer=(terms:import('./types.js').Contract,replacing?:number)=>{
    const employment=[...h.employment,{contractId:'prospective',studioId:b.studioId,terms,endedWeek:null,reason:'replacement' as const}]
    const activeEmploymentOrdinals=[...h.activeEmploymentOrdinals.filter(i=>i!==replacing),employment.length-1]
    return operatingReserve(b,{...h,employment,activeEmploymentOrdinals},week)
  }
  // Same renewal window and immediate replacement terms as the player's renewContract.
  // Ongoing work does not prevent an existing employer from retaining its own people.
  for(const ordinal of [...h.activeEmploymentOrdinals]) {
    const old=h.employment[ordinal]!
    if(old.studioId!==b.studioId||!renewalWindowOpen(old.terms,week))continue
    // P14A.1 (companion §2.1.3 / §2.5, the second bounded staff() edit): this loop
    // runs BEFORE decide() in the same weekly pass and would otherwise auto-renew a
    // rival's expiring person for 208 weeks in the discovery week, so a rival's
    // person could never reach a contested expiry. A CASE SUBJECT is excluded for
    // the whole open-case span — the exclusion lands with the case-open check, not
    // with settlement. Under a case the incumbent's retention is its PROPOSAL.
    if(caseOpenForTalent({...state,hollywood:h,talent},old.terms.talentId,week))continue
    const person=talent.find(t=>t.id===old.terms.talentId)!
    const terms=offerForTalent(state.seed,person,TUNING.HOLLYWOOD_CONTRACT_WEEKS,week)
    if(b.account.cash-terms.signingBonus<reserveAfterOffer(terms,ordinal))continue
    const contractId=`${b.studioId}:contract:${person.id}:${week}`
    const newOrdinal=h.employment.length
    h.employment=[...h.employment]
    h.employment[ordinal]={...old,endedWeek:week}
    h.employment.push({contractId,studioId:b.studioId,terms,endedWeek:null,reason:'renewal'})
    h.activeEmploymentOrdinals=h.activeEmploymentOrdinals.map(i=>i===ordinal?newOrdinal:i)
    moveRivalMoney(b.account,'signing',-terms.signingBonus,week)
    appendReceipt(h,{week,studioId:b.studioId,kind:'employment',talentId:person.id,fromStudioId:b.studioId,toStudioId:b.studioId,contractId,reason:'renewal'})
  }
  const occupied=busyTalentIds({...state,hollywood:h,talent})
  const unavailable=new Set([...occupied,...state.contracts.map(c=>c.talentId),...(state.founding?.applicantIds??[])])
  for(const e of h.activeEmploymentOrdinals.map(i=>h.employment[i]!))unavailable.add(e.terms.talentId)
  const own=currentEmployees(h,b.studioId)
  const filled=new Set<string>()
  let next=talent
  // P13B-S8: the fixed production team, then the Scientists this studio's own
  // research policy demands — one list, one contract law, one receipt per hire.
  for(const [slot,role] of [...RIVAL_TEAM_ROLES,...extraRoles].entries()) {
    const retained=own.find(e=>!filled.has(e.terms.talentId)&&next.find(t=>t.id===e.terms.talentId)?.role===role)
    if(retained){filled.add(retained.terms.talentId);continue}
    const expired=[...h.employment].reverse().find(e=>e.studioId===b.studioId && next.find(t=>t.id===e.terms.talentId)?.role===role && !filled.has(e.terms.talentId))
    let person=expired&&!unavailable.has(expired.terms.talentId)?next.find(t=>t.id===expired.terms.talentId):undefined
    person ??= next.find(t=>t.role===role&&!unavailable.has(t.id))
    let supplied=false
    if(!person) {
      const id=uniqueIdentity(`person-${b.studioId}-supply-${week}-${slot}`,new Set(next.map(t=>t.id)))
      person=generateIndustryTalent(state.seed,id,role);supplied=true
    }
    const terms=offerForTalent(state.seed,person,TUNING.HOLLYWOOD_CONTRACT_WEEKS,week)
    if(b.account.cash-terms.signingBonus < reserveAfterOffer(terms))continue
    if(supplied)next=[...next,person]
    const reason=expired?.terms.talentId===person.id?'renewal':'replacement'
    const contractId=`${b.studioId}:contract:${person.id}:${week}`
    h.activeEmploymentOrdinals=[...h.activeEmploymentOrdinals,h.employment.length]
    h.employment=[...h.employment,{contractId,studioId:b.studioId,terms,endedWeek:null,reason}]
    moveRivalMoney(b.account,'signing',-terms.signingBonus,week)
    appendReceipt(h,{week,studioId:b.studioId,kind:'employment',talentId:person.id,fromStudioId:null,toStudioId:b.studioId,contractId,reason})
    unavailable.add(person.id);filled.add(person.id)
  }
  return next

/** Stage rival work against pre-development talent. All writes are to new local objects. */
export function advanceHollywoodWeek(state:GameState):{hollywood:HollywoodState|null;talent:Talent[];growth:ReleaseGrowthRecord[];technology:GameState['technology'];physicalPlans:GameState['physicalPlans'];
  /** P14B.1 (1): this week's rival first takes (the 5 -> 4 advance), handed to
   * the outer tick so the ONE first-take root is appended in one place. */
  firstTakes:{studioId:string;production:Production}[]} {
  const source=state.hollywood
  if(!source)return {hollywood:null,talent:state.talent,growth:[],technology:state.technology,physicalPlans:state.physicalPlans,firstTakes:[]}
  const week=state.market.tick
  const h:HollywoodState={...source,businesses:source.businesses.map(b=>({...b,account:{...b.account,
    periods:b.account.periods.map((p,i)=>i===b.account.periods.length-1?{...p,movements:{...p.movements}}:p)}}))}
