// `currentTick`, the week `staff()` itself used.
let provenanced: GameState = { ...state, talent, talentProvenance: state.talentProvenance }
for (const person of industry.suppliedTalent) provenanced = withTalentProvenance(provenanced, person)
const materialized = materializeAges(provenanced, currentTick + 1)

let finalized: GameState = {
  // C2a-M4: the ADMITTED state is the base — it carries this advance's queue
  // (rows granted or expired are gone from it), the concepts an admitted
  // original commission minted, and the blueprint root that recorded them.
  ...admitted,
  technology: industry.technology,
  // P13B-S8: a rival's own admitted plans live on the shared plan root; the
  // player's admission at step 1.06 already wrote its rows into `admitted`.
  physicalPlans: industry.physicalPlans,
  hollywood,
  rngState: rng.serialize(),
  market: { ...state.market, tick: currentTick + 1 },
  talent: materialized.talent,
  talentProvenance: materialized.talentProvenance,
  studio: {

    if(identity.role==='rival' && identity.enteredWeek===null && identity.eligibleWeek<=finalized.market.tick) {
      finalized=enterRival(finalized,identity.studioId,'scheduled')
    }
  }
  // P14A.1 (companion §2.1.8): the TERMINAL, fixed-order market step — appended
  // after the pipeline's last call, on the already-incremented week, never inside
  // `advanceHollywoodWeek`/`decide()`, which run pre-increment. By here the P10
  // expiry step has removed the subject's contract, scheduled rival entry has run,
  // and `finishHollywoodWeek` has closed the subject's interval and written the
  // `expiry` receipt the chooser receipt references.
  // P14B.1 (1): the ONE first-take append, on the week this advance PRODUCES,
  // for the player's advance and every rival's — one root, one ordinal sequence,
  // written before anything reads it. P14B.1 (6): promise outcomes are then
  // evaluated ONCE, before the terminal market step, so a promise kept or broken
  // this week is already a fact when the market ranks on trust.
  const takeEntries = [
    ...productionAdvance.firstTakes.map((production) => ({ studioId: finalized.hollywood?.playerStudioId ?? '', production })),
    ...industry.firstTakes,
  ]
  const withTakes = appendFirstTakes(
    finishHollywoodWeek(finishTechnologyWeek(finalized)),
    takeEntries,
    finalized.market.tick,
  )
  // P14B.5 (2): the ONE relationship seam, between the take append and the
  // promise evaluation — the takes are already a fact, the market has not yet
  // ranked on D5. Fed THIS advance's delta only: the same take entries, plus this
  // advance's release results (the player's `records` and every rival's
  // `industry.growth`), never a scan of a root.
  const withBonds = advanceRelationshipsWeek(
    withTakes,
    { takes: takeEntries, releases: [...records.map((r) => r.filmResult), ...industry.growth.map((r) => r.filmResult)] },
    finalized.market.tick,
  )
  return advanceTalentMarketWeek(advancePromisesWeek(withBonds))
}
